// rustorb C++ implementation of the InteropTest::Echo server, with stubs and
// skeletons generated by rustorb-idl -bc++11.

#include "abstracttest.h"
#include "anytest.h"
#include "common.h"
#include "customtest.h"
#include "echo_impl.h"
#include "valuetest.h"

// Binds obj at path, creating intermediate contexts as needed.
static void bind_name(IDL::traits<CosNaming::NamingContext>::ref_type root, const std::string& path,
                 IDL::traits<CORBA::Object>::ref_type obj) {
  CosNaming::Name name = to_name(path);
  auto ctx = root;
  for (size_t i = 0; i + 1 < name.size(); ++i) {
    CosNaming::Name component{name[i]};
    try {
      ctx = ctx->bind_new_context(component);
    } catch (const CosNaming::NamingContext::AlreadyBound&) {
      ctx = IDL::traits<CosNaming::NamingContext>::narrow(ctx->resolve(component));
    }
  }
  ctx->rebind(CosNaming::Name{name.back()}, obj);
}

int main(int argc, char** argv) {
  std::vector<std::string> orb_args;
  Options opt = parse_args(argc, argv, orb_args);
  try {
    auto orb = orb_init(orb_args);
    if (opt.suite == "value") {
      // The valuetype suite: ValueTest::ValueEcho, which also stops the
      // server.
      valuetest::register_factories(orb);
      auto poa = persistent_poa(orb, "ValueTest");
      auto oid = PortableServer::string_to_ObjectId("ValueEcho");
      poa->activate_object_with_id(oid, CORBA::make_reference<valuetest::ValueEchoImpl>(orb));
      auto root = root_context(orb, opt.timeout);
      bind_name(root, opt.name, poa->id_to_reference(oid));
      std::cout << "server ready: " << opt.name << std::endl;
      orb->run();
      orb->destroy();
      std::cout << "server stopped" << std::endl;
      return 0;
    }
    if (opt.suite == "custom") {
      // The custom valuetype suite: CustomTest::CustomEcho, which also
      // stops the server.
      customtest::register_factories(orb);
      auto poa = persistent_poa(orb, "CustomTest");
      auto oid = PortableServer::string_to_ObjectId("CustomEcho");
      poa->activate_object_with_id(oid, CORBA::make_reference<customtest::CustomEchoImpl>(orb));
      auto root = root_context(orb, opt.timeout);
      bind_name(root, opt.name, poa->id_to_reference(oid));
      std::cout << "server ready: " << opt.name << std::endl;
      orb->run();
      orb->destroy();
      std::cout << "server stopped" << std::endl;
      return 0;
    }
    if (opt.suite == "abstract") {
      // The abstract interface suite: AbstractTest::AbstractEcho, which
      // also stops the server.
      abstracttest::register_factories(orb);
      auto poa = persistent_poa(orb, "AbstractTest");
      auto oid = PortableServer::string_to_ObjectId("AbstractEcho");
      poa->activate_object_with_id(oid, CORBA::make_reference<abstracttest::AbstractEchoImpl>(orb));
      auto root = root_context(orb, opt.timeout);
      bind_name(root, opt.name, poa->id_to_reference(oid));
      std::cout << "server ready: " << opt.name << std::endl;
      orb->run();
      orb->destroy();
      std::cout << "server stopped" << std::endl;
      return 0;
    }
    if (opt.suite == "any") {
      // The stage 2 suite: AnyTest::AnyEcho, with an Echo object next to it
      // for the client to shut the server down.
      auto poa = persistent_poa(orb, "AnyTest");
      auto any_oid = PortableServer::string_to_ObjectId("AnyEcho");
      poa->activate_object_with_id(any_oid, CORBA::make_reference<anytest::AnyEchoImpl>());
      auto oid = PortableServer::string_to_ObjectId("Echo");
      poa->activate_object_with_id(oid, CORBA::make_reference<EchoImpl>(orb));
      auto root = root_context(orb, opt.timeout);
      bind_name(root, opt.name, poa->id_to_reference(any_oid));
      bind_name(root, opt.name + "-Echo", poa->id_to_reference(oid));
      std::cout << "server ready: " << opt.name << std::endl;
      orb->run();
      orb->destroy();
      std::cout << "server stopped" << std::endl;
      return 0;
    }
    auto poa = persistent_poa(orb, "InteropTest");

    auto servant = CORBA::make_reference<EchoImpl>(orb);
    auto oid = PortableServer::string_to_ObjectId("Echo");
    poa->activate_object_with_id(oid, servant);

    auto obj = poa->id_to_reference(oid);
    auto root = root_context(orb, opt.timeout);
    bind_name(root, opt.name, obj);
    std::cout << "server ready: " << opt.name << std::endl;

    orb->run();
    orb->destroy();
    std::cout << "server stopped" << std::endl;
  } catch (const CORBA::Exception& e) {
    std::cerr << "CORBA exception: " << e << std::endl;
    return 1;
  }
  return 0;
}
